<script setup>
import {ref,toRaw} from 'vue';
import FormDialog from './FormDialog.vue';
import PayrollMonthlyTemplate from './PayrollMonthlyTemplate.vue';
import {api} from '../services/accounting.js';
import {errorText} from '../locales/accounting.js';
import {payrollErrors} from '../locales/payroll.js';
import {emptyPayrollEmployee} from '../../../shared/payroll.js';
import {payrollAgreement as defaultAgreement,payrollReferencesFor} from '../../../shared/payroll-agreements.js';
import {cents,decimal} from '../../../shared/money.js';
const props=defineProps({employee:Object,defaultCode:String,agreement:{type:Object,required:true}}),emit=defineEmits(['close','saved']);
const payrollAgreement=props.agreement,payrollReferences=payrollReferencesFor(payrollAgreement.code),extraWord=payrollAgreement.extra_count===4?'cuatro':'tres';
const initial=props.employee?structuredClone(toRaw(props.employee.profile)):{...emptyPayrollEmployee(payrollAgreement),code:props.defaultCode||''},agreementChanged=!!props.employee&&(initial.agreement_code||defaultAgreement.code)!==payrollAgreement.code;
const profile=ref({...initial,monthly_template:initial.monthly_template??null,batch_excluded:initial.batch_excluded===true,agreement:payrollAgreement.name,agreement_code:payrollAgreement.code,agreement_reviewed:agreementChanged?false:initial.agreement_reviewed}),busy=ref(false),error=ref(''),reference=ref('');
const textFields=[['code','Código de trabajador'],['name','Nombre y apellidos'],['tax_id','NIF / NIE'],['ss_number','Número Seguridad Social'],['job_title','Puesto / categoría'],['contract_code','Código de contrato'],['address','Domicilio'],['iban','IBAN']];
const amounts=[['base_salary','Salario base por mes o día'],['seniority',payrollAgreement.seniority_label+' por mes o día'],['attendance_rate','Prima de asistencia por día efectivo'],['extra_annual','Total anual de las '+extraWord+' pagas extras']];
function applyReference(){const row=payrollReferences.find(row=>row.id===reference.value);if(!row)return;profile.value.salary_unit=row.unit;profile.value.base_salary=row.base;profile.value.job_title=row.label;profile.value.attendance_rate=row.attendance;profile.value.agreement_reviewed=false;extras();}
function extras(){try{profile.value.extra_annual=decimal((cents(profile.value.base_salary)+cents(profile.value.seniority))*BigInt((profile.value.salary_unit==='daily'?30:1)*payrollAgreement.extra_count));}catch{error.value='Revisa el salario y la antigüedad.';}}
async function save(){busy.value=true;error.value='';try{const value={...profile.value,work_percent:profile.value.work_percent===''?null:profile.value.work_percent,extra_annual:profile.value.extra_annual===''?null:profile.value.extra_annual,irpf_rate:profile.value.irpf_rate===''?null:profile.value.irpf_rate,accident_rate:profile.value.accident_rate===''?null:profile.value.accident_rate};const data=await api('/payroll/employees'+(props.employee?'/'+props.employee.id:''),{method:props.employee?'PUT':'POST',body:{profile:value,version:props.employee?.version||0}});emit('saved',data);}catch(cause){error.value=payrollErrors[cause.code]||errorText(cause);}finally{busy.value=false;}}
</script>
<template><FormDialog class="payroll-dialog" :title="employee?'Ficha del trabajador':'Nuevo trabajador'" :busy="busy" @close="emit('close')"><form class="payroll-form" @submit.prevent="save"><p v-if="error" class="notice error-notice" role="alert">{{ error }}</p><p v-if="agreementChanged" class="notice">El convenio de la empresa ha cambiado. Se conservan los importes de la ficha: revisa salario, complemento personal, extras y prorratas antes de confirmar el nuevo convenio.</p><fieldset :disabled="busy"><div class="payroll-fields"><label v-for="[key,label] in textFields" :key="key">{{ label }}<input v-model="profile[key]" :aria-label="label" :required="['code','name','job_title'].includes(key)" :maxlength="key==='code'?24:key==='contract_code'?3:key==='address'?250:key==='name'||key==='job_title'?160:34" /></label><label>Fecha de alta / antigüedad<input v-model="profile.employment_start" type="date" required /></label><label>Fecha de baja<input v-model="profile.employment_end" type="date" /></label><label>Grupo de cotización<select v-model="profile.contribution_group" aria-label="Grupo de cotización"><option v-for="group in 11" :key="group" :value="String(group)">{{ group }}</option></select></label><label>Jornada contratada (%)<input v-model="profile.work_percent" inputmode="decimal" placeholder="Pendiente de confirmar" /></label><label>Cotización por desempleo<select v-model="profile.unemployment"><option value="ordinary">Tipo ordinario · Trabajador 1,55 % / Empresa 5,50 %</option><option value="temporary">Temporal ordinario · Trabajador 1,60 % / Empresa 6,70 %</option><option value="excluded">Sin cuota de desempleo / FOGASA en el documento · Requiere cuotas revisadas</option></select></label></div><h3>Condiciones salariales</h3><p class="muted">Régimen general · {{ payrollAgreement.name }} · {{ payrollAgreement.code }}</p><div class="payroll-fields"><label>Referencia salarial publicada · {{ payrollAgreement.table_year }} ({{ payrollAgreement.table_status }})<select v-model="reference" aria-label="Referencia salarial" @change="applyReference"><option value="">Introducir importes revisados</option><option v-for="row in payrollReferences" :key="row.id" :value="row.id">{{ row.label }} · {{ row.base.replace('.',',') }} €/{{ row.unit==='daily'?'día':'mes' }}</option></select></label><label>Unidad del salario<select v-model="profile.salary_unit" aria-label="Unidad del salario"><option value="daily">Diario</option><option value="monthly">Mensual</option></select></label><label v-for="[key,label] in amounts" :key="key">{{ label }} (€)<input v-model="profile[key]" inputmode="decimal" :aria-label="label" :placeholder="key==='extra_annual'?'Pendiente de confirmar':undefined" /></label><label>Tipo de IRPF revisado (%)<input v-model="profile.irpf_rate" inputmode="decimal" aria-label="IRPF del trabajador" placeholder="Pendiente de revisar" /></label><label>Tarifa AT/EP de la empresa (%)<input v-model="profile.accident_rate" inputmode="decimal" aria-label="Tarifa accidentes" placeholder="Según actividad / ocupación" /></label></div><div class="actions"><button class="button small" type="button" @click="extras">Calcular {{ extraWord }} extras de salario y complemento</button><a :href="payrollAgreement.table_source" target="_blank" rel="noopener noreferrer">Consultar tabla publicada</a><a href="https://sede.agenciatributaria.gob.es/Sede/Retenciones.shtml" target="_blank" rel="noopener noreferrer">Calcular IRPF · AEAT</a></div><p class="payroll-help">El salario contractual debe reflejar la jornada y los pactos de la empresa. Confirma el grupo de cotización con los datos de afiliación. Referencia: tablas {{ payrollAgreement.table_status }} de {{ payrollAgreement.table_year }}. {{ payrollAgreement.extra_help }} Revisa las condiciones aplicables antes de generar las nóminas.</p><PayrollMonthlyTemplate :profile="profile" /><label>Observaciones de la ficha<textarea v-model="profile.notes" rows="5" maxlength="2000" aria-label="Observaciones de la ficha"></textarea></label><label class="checkbox-label"><input v-model="profile.prorated" type="checkbox" />{{ payrollAgreement.prorated_label }}</label><label class="checkbox-label"><input v-model="profile.agreement_reviewed" type="checkbox" />He comprobado categoría, salarios y condiciones del convenio aplicables al ejercicio.</label><label class="checkbox-label"><input v-model="profile.batch_excluded" type="checkbox" />Excluir de la creación de nóminas en grupo hasta revisar sus incidencias.</label><label class="checkbox-label"><input v-model="profile.active" type="checkbox" />Trabajador activo para nuevas nóminas.</label></fieldset><div class="dialog-actions"><button type="button" class="button" :disabled="busy" @click="emit('close')">Cancelar</button><button class="button primary" :disabled="busy">Guardar trabajador</button></div></form></FormDialog></template>
